entries[33999] = { ["name"] = "Cenarion War Hippogryph", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. The capabilities of this mount depend on your Riding skill and location.\nSummons and dismisses a rideable Cenarion War Hippogryph mount. The capabilities of this mount depend on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Cenarion Expedition\n- Exalted\n\n\"Members of the Cenarion Circle have shared a long and prosperous partnership with their hippogryph allies. When conflict is unavoidable, the Cenarion War Hippogryph is called into service.\"\nVendor:\nFedryen Swiftspear\nZone:\nZangarmarsh, Outland\nFaction:\nCenarion Expedition - Exalted\nCost:" }
