entries[34060] = { ["name"] = "Flying Machine", ["text"] = "Mount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses a Flying Machine. Requires 1 Outland Engineering skill to ride. This mount changes depending on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Outland Engineering (1)\nRequires Apprentice Riding\n\n\"The backbone of the Alliance air force is comprised predominantly of gnomish flying machines due to their maneuverability and speed.\"\nProfession:\nEngineering" }
entries[34061] = { ["name"] = "Turbo-Charged Flying Machine", ["text"] = "Mount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses a Turbo-Charged Flying Machine. Requires 75 Outland Engineering skill to ride. This mount changes depending on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Outland Engineering (75)\nRequires Apprentice Riding\n\n\"Only the most talented engineers have the courage and the mental stamina to create a flying machine that boasts stability and safety. Turbo-charging one is just crazy!\"\nProfession:\nEngineering" }
